window.ComfinoPaywallInit={init:()=>{const d=document.getElementById("comfino-iframe-container");if(null!==d.querySelector("#comfino-paywall-container"))ComfinoPaywallFrontend.logEvent("Comfino paywall iframe already initialized.","info",d);else{var b=ComfinoPaywallFrontend.createPaywallIframe(ComfinoPaywallData.paywallUrl,ComfinoPaywallData.paywallOptions),e=document.getElementById("payment_method_comfino"),a=0;"priceModifier"in e.dataset&&(a=parseInt(e.dataset.priceModifier),Number.isNaN(a)?a=0:
b.src+="&priceModifier="+a);ComfinoPaywallData.paywallOptions.onUpdateOrderPaymentState=c=>{ComfinoPaywallFrontend.logEvent("updateOrderPaymentState WooCommerce","debug",c);document.getElementById("comfino-loan-amount").value=c.loanAmount;document.getElementById("comfino-loan-type").value=c.loanType;document.getElementById("comfino-loan-term").value=c.loanTerm;document.getElementById("comfino-price-modifier").value=a};d.appendChild(b);ComfinoPaywallFrontend.init(e,b,ComfinoPaywallData.paywallOptions)}}};
"complete"===document.readyState?ComfinoPaywallInit.init():document.addEventListener("readystatechange",()=>{"complete"===document.readyState&&ComfinoPaywallInit.init()});
